update
`msg_record_target`
set `has_read` = true
where `channel_code` = #{channelType} and `user_id` = #{userId}

    and `msg_record_id` in (
    select `id` from `msg_record`
    where

        (
        1=1

            and `application_code` = #{group.appCode}


            and `msg_type` = #{group.msgType}


            and `msg_scene_code` = #{group.sceneCode}

        )

    )


    and `msg_record_id` in (
    select `id` from `msg_record`
    where



                (
                1=1

                    and `application_code` != #{group.appCode}


                    and `msg_type` != #{group.msgType}


                    and `msg_scene_code` != #{group.sceneCode}

                )



    )

update
`msg_record_target` `mrt`
inner join `msg_record` `mr` on `mr`.`id` = `mrt`.`msg_record_id`
set `has_read` = true
where `mrt`.`channel_code` = #{channelType}
and `mrt`.`user_id` = #{userId}
and `mrt`.`send_status` = true
and `mr`.`msg_type` = #{msgType}

update
`msg_record_target` `mrt`
inner join `msg_record` `mr` on `mr`.`id` = `mrt`.`msg_record_id`
set `has_read` = true
where `mrt`.`channel_code` = #{channelType}
and `mrt`.`user_id` = #{userId}
and `mrt`.`send_status` = true
and mr.`application_code` = #{applicationCode}

update `msg_record_target` set `deleted` = #{deleteTimestamp} where `msg_record_id` in ( select `id` from `msg_record` where `business_id` in
#{businessId}
)
